            <div className="p-6 border-t border-slate-900 bg-slate-950/50 flex justify-center flex-shrink-0">
               <button 
                onClick={onClose}
                className="px-10 py-3 bg-white text-black text-sm font-black uppercase tracking-widest rounded-full hover:bg-cyan-400 transition-colors"
               >
                 Confirm Updates
               </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';

interface CalendarProps {
  holidays: string[];
  extraWorkingDays: string[];
  onDateToggle: (date: string, isWeekend: boolean) => void;
}

export const Calendar: React.FC<CalendarProps> = ({ holidays, extraWorkingDays, onDateToggle }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year: number, month: number) => {
    return new Date(year, month, 1).getDay();
  };

  const formatDate = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  const days = [];
  for (let i = 0; i < firstDay; i++) {
    days.push(null);
  }
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(new Date(year, month, i));
  }

  const handlePrevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  const isWeekend = (date: Date) => {
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() && 
           date.getMonth() === today.getMonth() && 
           date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="w-full select-none max-w-lg mx-auto overflow-hidden">
      <div className="flex justify-between items-center mb-8 bg-slate-900/40 p-3 rounded-2xl border border-slate-800">
        <button 
            onClick={handlePrevMonth} 
            className="p-3 hover:bg-slate-800 rounded-xl text-slate-500 hover:text-cyan-400 transition-all active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
        </button>
        <h3 className="text-white font-black text-lg md:text-xl uppercase tracking-widest font-mono">
            {currentDate.toLocaleDateString('default', { month: 'long', year: 'numeric' })}
        </h3>
        <button 
            onClick={handleNextMonth} 
            className="p-3 hover:bg-slate-800 rounded-xl text-slate-500 hover:text-cyan-400 transition-all active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
            </svg>
        </button>
      </div>

      <div className="grid grid-cols-7 gap-2 mb-4">
        {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
            <div key={day} className="text-center text-[10px] text-slate-600 uppercase font-black tracking-widest py-1">
                {day}
            </div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-2">
        {days.map((date, index) => {
            if (!date) return <div key={`empty-${index}`} />;

            const weekend = isWeekend(date);
            const dateStr = formatDate(date);
            const today = isToday(date);

            const isOff = weekend ? !extraWorkingDays.includes(dateStr) : holidays.includes(dateStr);

            return (
                <motion.button
                    key={dateStr}
                    whileTap={{ scale: 0.9 }}
                    onClick={() => onDateToggle(dateStr, weekend)}
                    className={`
                        aspect-square rounded-xl flex flex-col items-center justify-center text-sm relative transition-all duration-300 border-2
                        ${isOff ? 'bg-cyan-500 border-cyan-400 text-black font-black shadow-[0_0_20px_rgba(34,211,238,0.3)]' : 
                          'bg-slate-900 border-slate-800 text-slate-500 hover:border-slate-600 hover:text-slate-300'}
                        ${today ? 'ring-2 ring-cyan-500/20' : ''}
                    `}
                >
                    <span className="relative z-10">{date.getDate()}</span>
                    {today && !isOff && (
                         <div className="absolute top-1 right-1 w-1.5 h-1.5 bg-cyan-400 rounded-full animate-pulse" />
                    )}
                </motion.button>
            );
        })}
      </div>

      <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-3 text-[10px] font-black uppercase tracking-widest">
        <div className="flex items-center gap-3 bg-slate-900/50 p-4 rounded-xl border border-slate-800">
            <div className="w-4 h-4 bg-cyan-500 border border-cyan-400 rounded-md shadow-[0_0_10px_rgba(34,211,238,0.4)] flex-shrink-0"></div>
            <span className="text-slate-400">Off Day (Holiday)</span>
        </div>
        <div className="flex items-center gap-3 bg-slate-900/50 p-4 rounded-xl border border-slate-800">
            <div className="w-4 h-4 bg-slate-950 border border-slate-800 rounded-md flex-shrink-0"></div>
            <span className="text-slate-400">Class Day (Working)</span>
        </div>
      </div>
    </div>
  );
};
